    const draw = e.draw; e.draw = function (ctx, ox, oy) { const p = LV.IMG.soldier_purple; LV.IMG.soldier_purple = LV.IMG[img]; draw.call(this, ctx, ox, oy); LV.IMG.soldier_purple = p; };
