    ctx.fillStyle = '#6a5a3a'; ctx.fillRect(X - 6, Y - 10 - bob, 12, 8); ctx.fillStyle = '#f85050'; ctx.fillRect(X - 4, Y - 8 - bob, 2, 2); ctx.fillRect(X + 2, Y - 8 - bob, 2, 2);
