    const ctx = this.ctx;
    if (d.floors) {
      const list = d.floors.slice().sort(function (a, b) { const n = function (f) { return f[0] === 'B' ? -+f.slice(1) : +f.slice(0, -1); }; return n(b) - n(a); });
      list.forEach(function (f, i) { LV.text(ctx, f, 222, 40 + i * 12, f === d.floorName ? '#f8d040' : '#5a6090'); });
    }
