  ratfence:     { name: 'the Fence', art: ['m', 'mouse'], scale: 2.4, tint: 'grayscale(0.4)', hp: 10, sp: 60, move: 'dash', weak: 'dazed', attacks: [['aim', 2.5, 3, 0.3, 'dark']] },
