  twinsnake:    { name: 'the Twin Snake', art: ['m', 'snake'], scale: 2.4, tint: 'hue-rotate(120deg)', hp: 10, sp: 50, move: 'chase', attacks: [['aim', 1.8, 2, 0.5, 'dark'], ['summon', 6, 'snake', 2]] },
